authorChecks.cmd:
node --input-type=module > /tmp/agp-admission-handoff.Ja61m7/static-output-01.txt 2>&1 <<'NODE'
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {execFileSync} from 'node:child_process';
const record=JSON.parse(fs.readFileSync('docs/reviews/admission-diagnostic-owner-handoff-checks.json'));
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const git=(cwd,...args)=>execFileSync('git',['-C',cwd,...args],{encoding:'utf8',maxBuffer:32<<20});
const agp=process.cwd(),owner='/home/apnex/taceng/context-lab';
assert.equal(git(agp,'rev-parse','HEAD').trim(),record.before.agpHead);
assert.equal(git(owner,'rev-parse','HEAD').trim(),record.before.contextLabHead);
const source=fs.readFileSync(record.placement.source);
const destination=fs.readFileSync(record.placement.destination);
assert.deepEqual(destination,source);
assert.equal(sha(source),record.placement.sha256);
assert.equal(source.length,record.placement.bytes);
assert.equal(git(owner,'diff','HEAD','--'),'');
assert.equal(git(owner,'ls-files','--others','--exclude-standard').trim(),'incoming/agp-admission-diagnostic-capability-request.md');
assert.equal(git(agp,'diff','--exit-code',record.before.agpHead,'--','docs/reviews','packages','cli','rustcli','schemas'),'');
const docs=['docs/reviews/admission-diagnostic-owner-request.md','docs/reviews/admission-diagnostic-owner-handoff.md'];
const checkedLinks=[];
for(const file of docs){
 for(const m of fs.readFileSync(file,'utf8').matchAll(/\[[^\]]+\]\(([^)]+)\)/g)){
  const target=path.resolve(path.dirname(file),m[1]);
  assert.ok(fs.existsSync(target),target);
  checkedLinks.push({file,target});
 }
}
const board=fs.readFileSync('docs/BOARD.md','utf8');
const rows=board.split('\n').filter(l=>l.startsWith('|')&&l.includes('\x60B53\x60'));
assert.equal(rows.length,record.before.boardRows.length);
assert.equal(rows[0],record.before.boardRows[0]);
assert.equal(rows.at(-1),record.before.boardRows.at(-1));
const replaceOnce=(s,a,b)=>{assert.equal(s.split(a).length,2);return s.replace(a,b);};
let reversed=board;
for(let i=1;i<rows.length-1;i++)reversed=replaceOnce(reversed,rows[i],record.before.boardRows[i]);
const newParagraph=[
'Actual deployed provider/account capabilities remain unknown; the director subsequently selected the bounded owner request.\\',
'The [handoff record](reviews/admission-diagnostic-owner-handoff.md) confirms local placement in context-lab with an exact retained copy, not acknowledgment or acceptance; direct delivery to the provider operators awaits their destinations.\\'
].join('\n');
const oldParagraph='Actual deployed provider/account capabilities remain unknown; the next recommendation is approval for a bounded owner request, not packet construction or an AGP-local evaluator project.\\';
reversed=replaceOnce(reversed,newParagraph,oldParagraph);
const beforeBoard=record.before.beforeFiles.find(x=>x.file==='docs/BOARD.md');
assert.equal(sha(reversed),beforeBoard.sha256);
assert.equal(Buffer.byteLength(reversed),beforeBoard.bytes);
assert.ok(!board.includes('Do we send the bounded capability request'));
for(const item of ['B53','B56']){
 const line=board.split('\n').find(l=>l.startsWith('| \x60'+item+'\x60 |')&&l.includes(' | \x60I'));
 assert.ok(line?.endsWith('| open |'));
}
const verification=fs.readFileSync('docs/VERIFICATION.md','utf8');
const start=verification.indexOf('### 4.46 Admission diagnostic owner handoff\n');
const end=verification.indexOf('## 5. Modular test architecture\n');
assert.ok(start>0&&end>start);
const originalVerification=verification.slice(0,start)+verification.slice(end);
const beforeVerification=record.before.beforeFiles.find(x=>x.file==='docs/VERIFICATION.md');
assert.equal(sha(originalVerification),beforeVerification.sha256);
assert.equal(Buffer.byteLength(originalVerification),beforeVerification.bytes);
const mechanisms=record.before.beforeFiles.find(x=>x.file==='docs/design/mechanisms.md');
assert.equal(sha(fs.readFileSync(mechanisms.file)),mechanisms.sha256);
const allDocs=[...docs,record.placement.destination,'docs/BOARD.md','docs/VERIFICATION.md'];
const identities=allDocs.map(file=>{const b=fs.readFileSync(file);return{file,bytes:b.length,sha256:sha(b)};});
console.log(JSON.stringify({
 outcome:'PASS - local placement identity, links, scope and record preservation only',
 identities,checkedLinks,
 board:{beforeSha256:beforeBoard.sha256,afterSha256:sha(board),beforeRows:record.before.boardRows,afterRows:rows,onlyDeclaredEdits:true,scoresStatusOrderPreserved:true},
 verification:{beforeSha256:beforeVerification.sha256,afterSha256:sha(verification),onlyAppendedSection:true},
 preserved:'Previously tracked AGP review/implementation areas and pre-existing mechanism edits; context-lab tracked files.',
 unproven:'Recipient acknowledgment, direct provider delivery and every runtime capability/readiness claim.'
},null,2));
NODE

